46			{"space in a parameter value", "/p?a=x y", "U+0020"},
47			{"newline in a parameter value", "/p?a=1&b=x\ny", "U+000A"},
48			{"tab in a valueless parameter", "/p?flag\t", "U+0009"},
49			{"space before the question mark", "/p ?a=1", "U+0020"},
50			{"space right after the question mark", "/p? a=1", "U+0020"},
51			{"first offender is the earlier space, not the later newline", "/a b\nc", "U+0020"},
52			{"first offender is a newline earlier than a later space", "/a\nb c", "U+000A"},
53			{"first offender is the null byte at the front", "/\x00a b", "U+0000"},
54		}
55		cfg := mustConfig(t, sampleConfig)
56		for _, tc := range cases {
57			t.Run(tc.name, func(t *testing.T) {
58				// The front door: ParseRequest rejects the decoded target.
59				req, f := ParseRequest(requestJSONString(t, "GET", tc.target))
60				if f == nil {
