75				// A caller that bypasses ParseRequest gets the same failure from
76				// Resolve, never a route selection or a partial resolution.
77				res, rf := Resolve(cfg, &Request{Method: "GET", Target: tc.target})
78				if rf == nil || rf.Code != "invalid_request" {
79					t.Fatalf("Resolve(%q): got %+v, want invalid_request", tc.target, rf)
80				}
81				if !strings.Contains(rf.Reason, tc.want) {
82					t.Fatalf("Resolve reason = %q, want substring %q", rf.Reason, tc.want)
83				}
84				if res != nil {
85					t.Fatalf("Resolve(%q): got success %+v, want no resolution", tc.target, res)
86				}
