91	// TestTargetJSONEscapesDecodedThenRejected proves the rule operates on the
92	// decoded target: JSON string escapes such as "\n", "\t" and "\u0000" become
93	// the literal control byte once decoded and are rejected as such.
94	func TestTargetJSONEscapesDecodedThenRejected(t *testing.T) {
95		cfg := mustConfig(t, sampleConfig)
96		cases := []struct {
97			name    string
98			jsonDoc string
99			want    string
100		}{
101			{"json newline escape", `{"method":"GET","target":"/api/orders\n"}`, "U+000A"},
102			{"json tab escape", `{"method":"GET","target":"/api/orders\t"}`, "U+0009"},
103			{"json carriage return escape", `{"method":"GET","target":"/api/orders\r"}`, "U+000D"},
104			{"json null escape in a parameter value", `{"method":"GET","target":"/api?x=1\u0000"}`, "U+0000"},
105			{"json uppercase unicode escape for del", `{"method":"GET","target":"/api/x\u007F"}`, "U+007F"},
106			{"json unicode escape for space", `{"method":"GET","target":"/api/orders next"}`, "U+0020"},
107		}
108		for _, tc := range cases {
109			t.Run(tc.name, func(t *testing.T) {
110				req, f := ParseRequest([]byte(tc.jsonDoc))
111				if f == nil || f.Code != "invalid_request" {
112					t.Fatalf("ParseRequest: got req=%+v f=%+v, want invalid_request", req, f)
113				}
114				if !strings.Contains(f.Reason, tc.want) {
115					t.Fatalf("reason = %q, want substring %q", f.Reason, tc.want)
116				}
