138	// target that would create a conflict, and a target whose offending parameter
139	// a remove or set rule would delete or overwrite all still fail as
140	// invalid_request rather than route_not_found, route_conflict or a success
141	// that laundered the byte away.
142	func TestTargetDirectCharacterCheckPrecedesRouting(t *testing.T) {
143		// No route matches the path; a direct newline must still be
144		// invalid_request, never route_not_found.
145		emptyCfg := mustConfig(t, `{"routes":[]}`)
146		res, f := Resolve(emptyCfg, &Request{Method: "GET", Target: "/nothing\n"})
