1	package main
2	
3	import (
4		"bytes"
5		"errors"
6		"os"
7		"os/exec"
8		"path/filepath"
9		"strings"
10		"testing"
11		"time"
12	)
13	
14	// These tests pin the timing contract of resolve at the real command entry:
15	// the configuration is judged before the request is awaited. A config the
16	// rules can prove invalid must fail immediately — even while the requesting
17	// program still holds the stdin pipe open and has sent nothing — instead of
18	// blocking on a request that may never arrive or surfacing later as
19	// invalid_request. A valid config, on the other hand, must keep waiting: a
20	// temporarily empty pipe or a half-delivered JSON request is neither a
21	// success nor an invalid_request, and only the completed request followed by
22	// EOF produces a result. Everything runs offline; the upstreams are never
23	// contacted.
24	
25	// resolveCLIProcess is one spawned resolve command whose stdin is a pipe the
26	// test controls, so the test decides when (and whether) request bytes arrive
27	// and when EOF happens.
28	type resolveCLIProcess struct {
29		cmd    *exec.Cmd
30		stdin  *os.File // write end; the child reads from the other end
31		stdout *bytes.Buffer
32		stderr *bytes.Buffer
33		done   chan error
34	
35		finished bool
36		waitErr  error
37	}
38	
39	// startResolveCLI writes config to a temp file and spawns the helper binary
40	// with "resolve <config>", leaving stdin open with no bytes sent yet.
41	func startResolveCLI(t *testing.T, config string) *resolveCLIProcess {
42		t.Helper()
43	
44		dir := t.TempDir()
45		configPath := filepath.Join(dir, "config.json")
46		if err := os.WriteFile(configPath, []byte(config), 0o600); err != nil {
47			t.Fatalf("write config: %v", err)
48		}
49	
50		cmd := exec.Command(os.Args[0], "-test.run=^TestHelperProcess$", "--", "resolve", configPath)
51		cmd.Env = append(os.Environ(), helperEnv+"=1")
52		stdinR, stdinW, err := os.Pipe()
53		if err != nil {
54			t.Fatalf("create stdin pipe: %v", err)
55		}
56		cmd.Stdin = stdinR
57		stdout := &bytes.Buffer{}
58		stderr := &bytes.Buffer{}
59		cmd.Stdout = stdout
60		cmd.Stderr = stderr
61		if err := cmd.Start(); err != nil {
62			stdinR.Close()
63			stdinW.Close()
64			t.Fatalf("start resolve helper: %v", err)
65		}
66		// The child holds its own copy of the read end; the parent only writes.
67		stdinR.Close()
68	
69		p := &resolveCLIProcess{
70			cmd:    cmd,
71			stdin:  stdinW,
72			stdout: stdout,
73			stderr: stderr,
74			done:   make(chan error, 1),
75		}
76		go func() { p.done <- cmd.Wait() }()
77		t.Cleanup(func() {
78			p.stdin.Close()
79			if !p.poll() {
80				cmd.Process.Kill()
81				<-p.done
82			}
83		})
84		return p
85	}
86	
87	// poll records the exit result if the command has finished and reports
88	// whether it has.
89	func (p *resolveCLIProcess) poll() bool {
90		if p.finished {
91			return true
92		}
93		select {
94		case p.waitErr = <-p.done:
95			p.finished = true
96		default:
97		}
98		return p.finished
99	}
100	
101	// awaitExit requires the command to finish within timeout and returns what
102	// the parent can observe. A command that is still blocked (for example
103	// waiting on a request it should not be waiting for) fails the test.
104	func (p *resolveCLIProcess) awaitExit(t *testing.T, timeout time.Duration, what string) resolveResult {
105		t.Helper()
106		if !p.poll() {
107			select {
108			case p.waitErr = <-p.done:
109				p.finished = true
110			case <-time.After(timeout):
111				t.Fatalf("%s: command did not exit within %s while stdin was still open; it must not wait for a request", what, timeout)
112			}
113		}
114		return p.result()
115	}
116	
117	// assertStillWaiting requires the command to remain running for the whole
118	// grace period: exiting early — with a success or an invalid_request — while
119	// the request is still incomplete fails the test.
120	func (p *resolveCLIProcess) assertStillWaiting(t *testing.T, grace time.Duration, what string) {
121		t.Helper()
122		time.Sleep(grace)
123		if p.poll() {
124			res := p.result()
125			t.Fatalf("%s: command exited while the request was still incomplete (exit %d, stdout %q, stderr %q); want it to keep waiting for stdin",
126				what, res.exitCode, res.stdout, res.stderr)
127		}
128	}
129	
130	// result converts the recorded wait error into the observable exit code.
131	func (p *resolveCLIProcess) result() resolveResult {
132		exitCode := 0
133		if p.waitErr != nil {
134			var exitErr *exec.ExitError
135			if errors.As(p.waitErr, &exitErr) {
136				exitCode = exitErr.ExitCode()
137			} else {
138				exitCode = -1
139			}
140		}
141		return resolveResult{stdout: p.stdout.Bytes(), stderr: p.stderr.Bytes(), exitCode: exitCode}
142	}
143	
144	// write sends more request bytes without closing the pipe.
145	func (p *resolveCLIProcess) write(t *testing.T, data string) {
146		t.Helper()
147		if _, err := p.stdin.Write([]byte(data)); err != nil {
148			t.Fatalf("write request bytes to stdin: %v", err)
149		}
150	}
151	
152	// endRequest closes the pipe, delivering EOF after whatever was written.
153	func (p *resolveCLIProcess) endRequest(t *testing.T) {
154		t.Helper()
155		if err := p.stdin.Close(); err != nil {
156			t.Fatalf("close stdin: %v", err)
157		}
158	}
159	
160	// assertCLIInvalidConfigFailure checks the shared failure contract for a
161	// config rejection: non-zero exit, completely empty stdout and exactly one
162	// JSON invalid_config object on stderr whose reason contains every want
163	// substring and none of forbidden.
164	func assertCLIInvalidConfigFailure(t *testing.T, res resolveResult, want, forbidden []string) {
165		t.Helper()
166		if res.exitCode == 0 {
167			t.Fatalf("exit code = 0, want non-zero")
168		}
169		if len(res.stdout) != 0 {
170			t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
171		}
172		var fail struct {
173			Code   string `json:"code"`
174			Reason string `json:"reason"`
175		}
176		decodeOneJSON(t, res.stderr, "stderr", &fail)
177		if fail.Code != "invalid_config" {
178			t.Fatalf("code = %q, want invalid_config", fail.Code)
179		}
180		for _, sub := range want {
181			if !strings.Contains(fail.Reason, sub) {
182				t.Errorf("reason = %q, want substring %q", fail.Reason, sub)
183			}
184		}
185		for _, sub := range forbidden {
186			if strings.Contains(fail.Reason, sub) {
187				t.Errorf("reason = %q must not contain %q", fail.Reason, sub)
188			}
189		}
190	}
191	
192	// TestResolveCLIBrokenConfigJSONFailsBeforeStdinEOF proves a syntactically
193	// broken config is rejected the moment it is read: the command exits non-zero
194	// on its own while the requesting program still holds stdin open and has sent
195	// nothing, stdout stays completely empty, and stderr carries exactly one JSON
196	// error with code invalid_config whose reason says the config JSON could not
197	// be parsed without guessing a route or rule position.
198	func TestResolveCLIBrokenConfigJSONFailsBeforeStdinEOF(t *testing.T) {
199		p := startResolveCLI(t, `{"routes":[ broken`)
200	
201		res := p.awaitExit(t, 10*time.Second, "broken config JSON")
202		assertCLIInvalidConfigFailure(t, res,
203			[]string{"not valid JSON"},
204			[]string{"route 1", "route 2", "queryTransforms rule", "invalid_request"})
205	}
