207	// TestResolveCLIInvalidRenameRuleFailsBeforeStdinEOF proves a structurally
208	// invalid rule on a later route rejects the whole configuration before any
209	// request is awaited: route 1 would answer every request, but route 2's
210	// second queryTransforms rule is a rename without "to", so the command exits
211	// non-zero while stdin is still open. The reason keeps the 1-based route
212	// position, the route id and the 1-based rule index, and must not mislabel
213	// the rule error as broken config JSON.
214	func TestResolveCLIInvalidRenameRuleFailsBeforeStdinEOF(t *testing.T) {
215		config := `{
216		  "routes": [
217		    {"id": "hit", "methods": ["*"], "pathPrefix": "/",
218		     "upstream": "http://hit.internal"},
219		    {"id": "admin", "methods": ["GET"], "pathPrefix": "/admin",
220		     "upstream": "http://admin.internal",
221		     "queryTransforms": [
222		       {"op": "set", "name": "a", "value": "1"},
223		       {"op": "rename", "name": "old"}
224		     ]}
225		  ]
226		}`
227		p := startResolveCLI(t, config)
