229		res := p.awaitExit(t, 10*time.Second, "invalid rename rule")
230		assertCLIInvalidConfigFailure(t, res,
231			[]string{"route 2", `"admin"`, "rule 2"},
232			[]string{"not valid JSON", "invalid_request"})
233	}
