235	// TestResolveCLIValidConfigWaitsForCompleteRequest proves a valid config
236	// keeps the command waiting on stdin: a temporarily empty pipe and a
237	// half-delivered JSON request produce neither a success nor an
238	// invalid_request. Once the rest of the request arrives and stdin closes,
239	// the command resolves it by the usual rules — matched routeId, joined
240	// upstreamURL — with empty stderr.
241	func TestResolveCLIValidConfigWaitsForCompleteRequest(t *testing.T) {
242		p := startResolveCLI(t, cliSuccessConfig)
243	
